package com.axsos.Life.models; import jakarta.persistence.*; import java.time.*; import java.util.*; import static com.axsos.Life.models.Enums.*;
@Entity @Table(name="meal_circle_sessions") public class MealCircleSession extends BaseEntity {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) private User creator; private String cuisineCategory; private String city; @Enumerated(EnumType.STRING) private MealCircleStatus status=MealCircleStatus.DRAFT; private String sharedMealTitle; private Integer sharedMealCalories; @Column(length=2500) private String sharedMealDescription; @Column(length=2500) private String aiExplanation; private LocalDateTime generatedAt; private LocalDateTime expiresAt; private boolean viewed;
 @OneToMany(mappedBy="session",cascade=CascadeType.ALL,orphanRemoval=true) private List<MealCircleMember> members=new ArrayList<>();
 public Long getId(){return id;} public void setId(Long v){id=v;} public User getCreator(){return creator;} public void setCreator(User v){creator=v;} public String getCuisineCategory(){return cuisineCategory;} public void setCuisineCategory(String v){cuisineCategory=v;} public String getCity(){return city;} public void setCity(String v){city=v;} public MealCircleStatus getStatus(){return status;} public void setStatus(MealCircleStatus v){status=v;} public String getSharedMealTitle(){return sharedMealTitle;} public void setSharedMealTitle(String v){sharedMealTitle=v;} public Integer getSharedMealCalories(){return sharedMealCalories;} public void setSharedMealCalories(Integer v){sharedMealCalories=v;} public String getSharedMealDescription(){return sharedMealDescription;} public void setSharedMealDescription(String v){sharedMealDescription=v;} public String getAiExplanation(){return aiExplanation;} public void setAiExplanation(String v){aiExplanation=v;} public LocalDateTime getGeneratedAt(){return generatedAt;} public void setGeneratedAt(LocalDateTime v){generatedAt=v;} public LocalDateTime getExpiresAt(){return expiresAt;} public void setExpiresAt(LocalDateTime v){expiresAt=v;} public boolean isViewed(){return viewed;} public void setViewed(boolean v){viewed=v;} public List<MealCircleMember> getMembers(){return members;} public void setMembers(List<MealCircleMember> v){members=v;}
}
